WITH item_sales AS (SELECT ss_item_sk, SUM(ss_ext_sales_price) AS total_sales_price, SUM(ss_net_profit) AS total_sales_profit FROM store_sales GROUP BY ss_item_sk), returns_detail AS (SELECT wr.wr_reason_sk, wr.wr_return_amt_inc_tax, wr.wr_net_loss, wr.wr_refunded_customer_sk, c.c_birth_year, isales.total_sales_price, isales.total_sales_profit FROM web_returns wr JOIN customer c ON wr.wr_refunded_customer_sk = c.c_customer_sk LEFT JOIN item_sales isales ON wr.wr_item_sk = isales.ss_item_sk), reason_agg AS (SELECT rd.wr_reason_sk, COUNT(*) AS return_cnt, SUM(rd.wr_return_amt_inc_tax) AS total_return_amount, AVG(rd.wr_return_amt_inc_tax) AS avg_return_amount, SUM(rd.wr_net_loss) AS total_net_loss, AVG(rd.wr_net_loss) AS avg_net_loss, AVG(rd.total_sales_price) AS avg_original_sales_price, AVG(rd.total_sales_profit) AS avg_original_sales_profit FROM returns_detail rd GROUP BY rd.wr_reason_sk) SELECT r.r_reason_desc, a.return_cnt, a.total_return_amount, a.avg_return_amount, a.total_net_loss, a.avg_net_loss, DENSE_RANK() OVER (ORDER BY a.total_net_loss DESC) AS loss_rank, SUM(a.total_net_loss) OVER (ORDER BY a.total_net_loss DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_loss, a.avg_original_sales_price, a.avg_original_sales_profit FROM reason_agg a JOIN reason r ON a.wr_reason_sk = r.r_reason_sk ORDER BY a.total_net_loss DESC
